{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"New Jersey Security Deposit Law","requirement":"A landlord may not demand a security deposit above one and one-half times one month's rent, may not raise the deposit more than 10% a year, and must return the deposit plus interest within 30 days after the tenancy ends.","key_value":"1.5 months' rent; annual deposit increase max 10%","coverage_conditions":"Residential rentals in New Jersey. The deposit-account section does not apply to security deposits for seasonal use or rental of not more than 125 consecutive days.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Seasonal use or rental (125 consecutive days or less) excluded from deposit-account rules"},"exemptions":"Security deposits for seasonal use or rental, meaning use or rental for a term of not more than 125 consecutive days by a person having a permanent residence elsewhere.","penalty":"Tenant may sue for double the amount of the security deposit contended to be wrongfully withheld, plus court costs and reasonable attorney's fees.","effective_date":null,"citation":"N.J.S.A. 46:8-21.2","quoted_span":"The maximum-security deposit to be collected by the landlord cannot be more than one and one-half times one month’s rent ( N.J.S.A. 46:8-21.2 ). It can be less. Any additional yearly security deposit increase may not exceed 10% of the current security deposit.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"Safe Housing Act security deposit return after domestic violence termination","requirement":"When a tenant ends a lease under the Safe Housing Act because of domestic violence, the landlord must make the deposit plus interest available within 15 business days and notify the tenant within three business days where and when to collect it.","key_value":"15 business days","coverage_conditions":"Tenants who terminate a lease under the Safe Housing Act after providing notice and proof of domestic violence.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":"This law does not apply to transient or seasonal rentals.","penalty":null,"effective_date":null,"citation":"N.J.S.A. 46:8-9.6","quoted_span":"Within 15 business days after the lease is terminated, the landlord shall make available the return of the tenant’s security deposit, plus any interest earned, to the tenant or the tenant’s agent.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
